-- Apex Digital Bank | Portfolio 2 synthetic NON-POSTED workload
-- REVIEW BEFORE RUNNING. Run only on local educational database.
-- Preserves all pre-existing customer accounts and balances.
-- No DROP TABLE, DELETE, UPDATE of existing balances, or foreign-key disabling.
-- Synthetic transaction records are pending/non-posted: no ledger entries.
USE apex_digital_bank;
SET @p2_scheme_id = (SELECT scheme_id FROM account_schemes WHERE is_active = 1 ORDER BY scheme_id LIMIT 1);
SET @p2_status_id = (SELECT status_id FROM transaction_statuses WHERE is_terminal = 0 ORDER BY status_id LIMIT 1);
-- Confirm both variables are non-NULL before running the inserts.
SELECT @p2_scheme_id AS selected_scheme_id, @p2_status_id AS selected_nonterminal_status_id;
START TRANSACTION;
-- Existing bank accounts are untouched. Synthetic accounts start with zero balances.
-- Use a scheme selected from the existing lookup table.
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0000001' AND 'P2C0000500'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0000501' AND 'P2C0001000'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0001001' AND 'P2C0001500'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0001501' AND 'P2C0002000'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0002001' AND 'P2C0002500'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0002501' AND 'P2C0003000'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0003001' AND 'P2C0003500'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0003501' AND 'P2C0004000'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0004001' AND 'P2C0004500'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
SELECT c.customer_id, @p2_scheme_id, CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')),
       CONCAT(c.first_name, ' ', c.last_name), 'NGN', 'ACTIVE', 'ACTIVE', 'ACTIVE', 0, 0,
       '2025-01-01 00:00:00', '2025-01-01 00:00:00'
FROM customers c WHERE c.customer_number BETWEEN 'P2C0004501' AND 'P2C0005000'
  AND NOT EXISTS (SELECT 1 FROM bank_accounts a WHERE a.account_number = CONCAT('P2A', LPAD(SUBSTRING(c.customer_number,4),7,'0')));
-- Staging table exists only in this session; no permanent schema changes.
CREATE TEMPORARY TABLE IF NOT EXISTS p2_transaction_stage (
  transaction_reference VARCHAR(64) PRIMARY KEY,
  account_number VARCHAR(20) NOT NULL,
  direction VARCHAR(10) NOT NULL,
  amount DECIMAL(19,4) NOT NULL,
  transaction_date DATETIME(6) NOT NULL
) ENGINE=InnoDB;
-- NON-POSTED transactions only. Do not interpret as successful financial movements.
-- The existing transaction statuses lookup determines the nonterminal status.
 amount, currency, narration, transaction_date, created_at)
SELECT s.transaction_reference, a.account_id, @p2_status_id, s.direction,
       'PERFORMANCE_TEST', s.amount, 'NGN', 'Synthetic pending workload; not posted',
       s.transaction_date, s.transaction_date
FROM p2_transaction_stage s
JOIN bank_accounts a ON a.account_number = s.account_number;
COMMIT;
-- Verification: expected 5000 customers, 5000 accounts, 100000 transactions.
SELECT COUNT(*) AS portfolio2_customers FROM customers WHERE customer_number LIKE 'P2C%';
SELECT COUNT(*) AS portfolio2_accounts FROM bank_accounts WHERE account_number LIKE 'P2A%';
SELECT COUNT(*) AS portfolio2_transactions FROM transactions WHERE transaction_reference LIKE 'P2-TXN-%';
SELECT COALESCE(SUM(available_balance),0) AS synthetic_available_balance,
       COALESCE(SUM(ledger_balance),0) AS synthetic_ledger_balance
FROM bank_accounts WHERE account_number LIKE 'P2A%';
DROP TEMPORARY TABLE IF EXISTS p2_transaction_stage;
